logic.admin/create_market.rs:
// Admin: your backend lists a market. Its id unused, two tokens, a tick and a lot of at least 1, and a fee of
// at most the notional. A price is quote units a lot, whole ticks; a size is base units, whole lots.
pub fn create_market(s: &mut State<'_>, a: &CreateMarket) {
    assert!(s.get::<Markets>(&a.market).is_none(), "market_exists");
    assert!(a.base != a.quote, "same_token");
    assert!(a.tick >= 1 && a.lot >= 1, "zero_tick_or_lot");
    assert!(a.fee_bps <= 10_000, "fee_too_high");
    s.put::<Markets>(&a.market, &Market { base: a.base, quote: a.quote, tick: a.tick, lot: a.lot,
        status: MarketStatus::Open, fee_bps: a.fee_bps });
}

logic.admin/set_market_status.rs:
// Admin: your backend halts, reopens or delists a market. Another status than the market's own; a delisted
// market stays delisted. order settles nothing on a market that is not open.
pub fn set_market_status(s: &mut State<'_>, a: &SetMarketStatus) {
    let mut m = s.must::<Markets>(&a.market);
    assert!(m.status != MarketStatus::Delisted, "delisted");
    assert!(a.status != m.status, "same_status");
    m.status = a.status;
    s.put::<Markets>(&a.market, &m);
}

logic.signed/swap.rs:
// Signed by parties(2): one message, both parties' signatures, under a context that names them in order. The
// framework draws on both lanes, so it applies once: both legs move, each from its own party's balance, or neither
// does. Each party signs on a fresh lane, so lane 0 stays free while the agreement is pending.
pub fn swap(s: &mut State<'_>, a: &Signed<Swap>) {
    assert!(a.give_a > 0 && a.give_b > 0, "empty_swap");
    let (pa, pb) = (a.party(0), a.party(1));
    s.balances.transfer(&pa, &pb.address(), &a.give_a_token, a.give_a);
    s.balances.transfer(&pb, &pa.address(), &a.give_b_token, a.give_b);
}

logic.admin/set_fee_recipient.rs:
// Admin: takers' fees go to one recipient, Config's one row, id 0.
pub fn set_fee_recipient(s: &mut State<'_>, a: &SetFeeRecipient) {
    s.put::<Config>(&0, &a.fee_to);
}

logic.settled/order.rs:
// Settled, fillable on qty: a market's orders, which your backend matched, settled on its fills, in its order.
// The framework has checked each order's signature, expiry and lane, so its fill is at most what its lane has left.
// The logic holds every guarantee an order relies on: every order is of the settlement's market, which is open; each
// fill is between a maker and a taker among the unit's orders on opposite sides, the taker not post only, at a price
// of whole ticks within both limits, of whole lots; and each order's fills add up to its fill. A fill moves the base
// from the seller to the buyer and the notional, price · qty / lot, from the buyer to the seller; the taker pays the
// fee to Config's recipient, read only for a market with a fee.
pub fn order(s: &mut State<'_>, u: &Settled<Order, Fills>) {
    let orders = u.requests();
    let settlement = u.settlement();
    let mut i = 0;
    while i < orders.len() {
        assert!(orders[i].market == settlement.market, "other_market");
        i += 1;
    }
    let m = s.must::<Markets>(&settlement.market);
    assert!(m.status == MarketStatus::Open, "market_not_open");
    let fee_to = if m.fee_bps == 0 { None } else { Some(s.must::<Config>(&0)) };
    let (lot, bps) = (m.lot as u128, m.fee_bps as u128);
    let fills = &settlement.fills;
    let mut filled: Vec<u128> = Vec::with_capacity(orders.len());
    i = 0;
    while i < orders.len() {
        filled.push(0);
        i += 1;
    }
    i = 0;
    while i < fills.len() {
        let f = &fills[i];
        let (mk, tk) = (f.maker as usize, f.taker as usize);
        assert!(mk < orders.len() && tk < orders.len(), "unknown_order");
        let (maker, taker) = (&orders[mk], &orders[tk]);
        assert!(maker.side != taker.side, "same_side");
        assert!(taker.tif != Tif::PostOnly, "post_only_taker");
        let (buy, sell) = match maker.side { Side::Buy => (maker, taker), Side::Sell => (taker, maker) };
        assert!(f.price >= m.tick && f.price.is_multiple_of(m.tick), "off_tick");
        assert!(f.price <= buy.limit && f.price >= sell.limit, "outside_limit");
        assert!(f.qty >= lot && f.qty.is_multiple_of(lot), "off_lot");
        let quote = (f.price as u128).checked_mul(f.qty / lot).expect("notional_overflow");
        s.balances.transfer_from(sell, buy.signer(), &m.base, f.qty);
        s.balances.transfer_from(buy, sell.signer(), &m.quote, quote);
        if let Some(to) = &fee_to {
            let fee = quote / 10_000 * bps + quote % 10_000 * bps / 10_000; // no product passes 2^128
            s.balances.transfer_from(taker, to, &m.quote, fee);
        }
        filled[mk] = filled[mk].checked_add(f.qty).expect("fill_overflow");
        filled[tk] = filled[tk].checked_add(f.qty).expect("fill_overflow");
        i += 1;
    }
    i = 0;
    while i < orders.len() {
        assert!(filled[i] == orders[i].fill(), "fills_do_not_add_up"); // an order trades exactly what its lane gives up
        i += 1;
    }
}
